:root {
  --navy: #0a0a23;
  --navy-soft: #16163a;
  --amber: #f2b94b;
  --amber-dark: #d79d2f;
  --bg: #f8f9fc;
  --surface: #ffffff;
  --text: #16181d;
  --muted: #5c6370;
  --border: #e6e8ef;
  --radius: 14px;
  --shadow: 0 10px 28px rgba(10, 10, 35, 0.08);
  --shadow-hover: 0 16px 38px rgba(10, 10, 35, 0.12);
  --font: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.55;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.container {
  width: min(1120px, calc(100% - 2rem));
  margin: 0 auto;
}

.site-header {
  background: var(--navy);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 40;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 72px;
}

.brand {
  font-weight: 800;
  letter-spacing: 0.2px;
  font-size: 1.1rem;
}

.nav-links {
  display: flex;
  gap: 1.3rem;
  align-items: center;
}

.nav-link {
  color: #e8e9f4;
  font-weight: 500;
  font-size: 0.95rem;
  transition: color 180ms ease;
}

.nav-link:hover,
.nav-link.active { color: #fff; }

.donate-link {
  background: var(--amber);
  color: #1a1608;
  padding: 0.5rem 0.85rem;
  border-radius: 10px;
  font-weight: 700;
}
.donate-link:hover { background: var(--amber-dark); }

.menu-btn {
  background: transparent;
  border: 1px solid rgba(255,255,255,0.25);
  color: #fff;
  border-radius: 10px;
  width: 42px;
  height: 42px;
  display: none;
  place-items: center;
  cursor: pointer;
}

.mobile-menu {
  display: none;
  padding-bottom: 1rem;
}
.mobile-menu.open { display: grid; gap: 0.5rem; }
.mobile-menu a {
  color: #f3f4ff;
  padding: 0.55rem 0.2rem;
  font-weight: 500;
}

.page-main { padding: 2.4rem 0 4rem; }

.hero {
  margin-bottom: 2.4rem;
}
.hero h1 {
  margin: 0 0 0.7rem;
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.hero p {
  margin: 0;
  color: var(--muted);
  max-width: 70ch;
}

.section-title {
  margin: 0 0 1.1rem;
  font-size: 1.4rem;
  letter-spacing: -0.01em;
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform 180ms ease, box-shadow 180ms ease;
}
.card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.card-thumb {
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.card-body {
  padding: 0.95rem;
}

.tag {
  display: inline-block;
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  margin-bottom: 0.7rem;
}
.tag-ai { background: #e9edff; color: #21337a; }
.tag-scrape { background: #fff3df; color: #7e4f00; }
.tag-db { background: #e7f7ee; color: #17603f; }
.tag-search { background: #efe9ff; color: #522d90; }
.tag-data { background: #eaf6ff; color: #0d4f8a; }

.card-title {
  margin: 0 0 0.8rem;
  font-size: 1.03rem;
  line-height: 1.35;
}

.meta {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  color: var(--muted);
  font-size: 0.85rem;
}
.meta img {
  width: 30px;
  height: 30px;
  border-radius: 50%;
}

.load-wrap { text-align: center; margin-top: 1.5rem; }
.btn {
  border: 0;
  border-radius: 11px;
  padding: 0.7rem 1.05rem;
  font-weight: 700;
  cursor: pointer;
}
.btn-primary {
  background: var(--navy);
  color: #fff;
}
.btn-primary:hover { background: #17174a; }

.syllabus {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.syllabus-item {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 1rem;
  border-bottom: 1px solid var(--border);
}
.syllabus-item:last-child { border-bottom: 0; }
.syllabus-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: #f0f2f8;
  font-size: 1rem;
}

.donate-layout {
  display: grid;
  grid-template-columns: 1.25fr 0.95fr;
  gap: 1rem;
}
.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1rem;
}

.amount-tabs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.6rem;
  margin: 1rem 0;
}
.amount-btn {
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 10px;
  padding: 0.6rem;
  font-weight: 700;
  cursor: pointer;
}
.amount-btn.active {
  background: #fff7e8;
  border-color: #f0c163;
  color: #684107;
}

.bullets { margin: 0; padding-left: 1.05rem; color: #2e3340; }
.bullets li { margin: 0.35rem 0; }

.faq-item {
  border: 1px solid var(--border);
  border-radius: 10px;
  margin-bottom: 0.6rem;
  overflow: hidden;
}
.faq-q {
  width: 100%;
  text-align: left;
  border: 0;
  background: #fff;
  padding: 0.8rem 0.9rem;
  font-weight: 650;
  cursor: pointer;
}
.faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height 260ms ease, padding 260ms ease;
  padding: 0 0.9rem;
  color: var(--muted);
}
.faq-item.open .faq-a {
  max-height: 200px;
  padding: 0 0.9rem 0.85rem;
}

.tag-header {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  margin-bottom: 1rem;
}

.popular-tags {
  display: flex;
  gap: 0.65rem;
  flex-wrap: wrap;
  margin: 0.8rem 0 1.2rem;
}
.popular-tags a {
  display: inline-flex;
  gap: 0.35rem;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0.42rem 0.72rem;
  color: #30364a;
  font-size: 0.86rem;
}

.site-footer {
  border-top: 1px solid var(--border);
  background: #fff;
  padding: 1.3rem 0;
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 960px) {
  .articles-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .donate-layout { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .nav-links { display: none; }
  .menu-btn { display: grid; }
  .articles-grid { grid-template-columns: 1fr; }
  .page-main { padding-top: 1.5rem; }
}
